  readonly id: EnvironmentId
  /** Declared kind. */
  readonly kind: K
  /** Human-readable name. */
  readonly name: string
  /** What the task establishes, stated for people and models. */
  readonly description: string
  /** The task statement and its fixture. */
  readonly task: EnvironmentTask
  /**
