function finding(output: string): string {
  const lines = output.split('\n').map(line => line.replace(/\s+/gu, ' ').trim()).filter(line => line !== '')
  const line = lines.find(candidate => /error|fail|panic|cannot|could not|not found|no tests/iu.test(candidate)) ?? lines.at(-1) ?? 'no output'
  return line.length > 240 ? `${line.slice(0, 240)}...` : line
