/**
 * The held-out split: in each track, the admitted exercises ranked by a seeded
 * SHA-256 of their ids, the first fifth held out. The rank of one id depends on
 * the id alone, so admitting or refusing another exercise moves at most the
 * boundary of the split.
 * @param admitted - every admitted environment id.
 * @returns the held-out ids.
 */
export function heldOutIds(admitted: readonly string[]): ReadonlySet<string> {
  const rank = (id: string): string => createHash('sha256').update(`${HELD_OUT_SEED}\n${id}`).digest('hex')
  const held = new Set<string>()
  for (const language of POLYGLOT_LANGUAGES) {
    const ids = admitted.filter(id => languageOf(id) === language).sort((left, right) => (rank(left) < rank(right) ? -1 : 1))
    for (const id of ids.slice(0, Math.round(ids.length * HELD_OUT_SHARE))) held.add(id)
  }
  return held
}

