    print('==', path.split('/')[-2][-60:])
    shown_prompt = False
    for line in open(path):
        event = json.loads(line)
        kind = event.get('type')
        data = event.get('data', {})
        if kind == 'user/message' and not shown_prompt and len(sys.argv) > 2:
            content = data.get('message', {}).get('content')
            text = content if isinstance(content, str) else json.dumps(content)[:4000]
            print('PROMPT:', text[-1500:])
            shown_prompt = True
        if kind == 'assistant/message':
            for part in data.get('message', {}).get('content', []):
