"""For each session of a record, print bash calls that search outside the workspace and the start of their results."""
import json, glob, os, sys
record = sys.argv[1]
for path in sorted(glob.glob(os.path.join(record, 'sessions', '*.jsonl'))):
    env = None
    calls = {}
    for line in open(path):
        event = json.loads(line)
        kind, data = event.get('type'), event.get('data', {})
        if kind == 'environment/run':
            env = data.get('environmentId')
        if kind == 'assistant/message':
            for part in data.get('message', {}).get('content', []):
                if part.get('type') == 'tool-call' and part.get('name') == 'bash':
