"""Print every tool call of one environment's session whose arguments name the run directory outside the cell, with its result."""
import json, glob, os, sys
record, environment, run_dir = sys.argv[1], sys.argv[2], sys.argv[3]
for path in glob.glob(os.path.join(record, 'sessions', '*.jsonl')):
    events = [json.loads(line) for line in open(path)]
    if not any(e.get('type') == 'environment/run' and e['data'].get('environmentId') == environment for e in events):
        continue
    workspace = next(e['data']['header']['cwd'] for e in events if e.get('type') == 'session' and 'header' in e.get('data', {})) if any(e.get('type') == 'session' and 'header' in e.get('data', {}) for e in events) else None
    print('workspace', workspace)
    calls = {}
    for e in events:
        if e.get('type') == 'assistant/message':
            for part in e['data']['message']['content']:
                if part.get('type') == 'tool-call' and run_dir in part.get('arguments', ''):
                    args = part.get('arguments', '')
                    stripped = args.replace(workspace or '\0', '')
                    if run_dir in stripped:
                        calls[part['id']] = (part['name'], args)
        if e.get('type') == 'tool/result':
            for part in e['data']['message']['content']:
                if part.get('toolCallId') in calls:
                    name, args = calls.pop(part['toolCallId'])
                    text = ' '.join(c.get('text', '') for c in part.get('content', []))
                    print('CALL', name, args[:600])
                    print('RESULT', text[:800])

